// /data/data/<pkg>/ is chmod 0700 to its own UID — the kernel refuses before
// any app code runs, and SELinux adds a policy check on top of that.
fun tryReadAnotherApp(pkg: String): String? = try {
    java.io.File("/data/data/$pkg/shared_prefs/secrets.xml").readText()
} catch (e: SecurityException) {
    null   // sandbox + SELinux; there is no way to opt out
}

fun encryptToFile(plain: ByteArray): ByteArray {
    val key = getOrCreateAesKey(KEY_ALIAS)      // non-exportable Keystore key
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.ENCRYPT_MODE, key)
    val iv = cipher.iv
    val ct = cipher.doFinal(plain)
    return iv + ct                              // store IV alongside ciphertext
}

fun decryptFromFile(data: ByteArray): ByteArray {
    val key = getOrCreateAesKey(KEY_ALIAS)
    val iv = data.copyOfRange(0, 12)
    val ct = data.copyOfRange(12, data.size)
    val cipher = Cipher.getInstance("AES/GCM/NoPadding")
    cipher.init(Cipher.DECRYPT_MODE, key, GCMParameterSpec(128, iv))
    return cipher.doFinal(ct)
}

fun promptLogin(activity: FragmentActivity) {
    val canAuth = BiometricManager.from(activity)
        .canAuthenticate(BIOMETRIC_STRONG or DEVICE_CREDENTIAL)
    if (canAuth != BiometricManager.BIOMETRIC_SUCCESS) {
        promptEnrollment(activity)   // ACTION_BIOMETRIC_ENROLL or device lock
        return
    }

    val promptInfo = BiometricPrompt.PromptInfo.Builder()
        .setTitle("Unlock your vault")
        .setAllowedAuthenticators(BIOMETRIC_STRONG or DEVICE_CREDENTIAL)
        .build()

    val cipher = getAuthCipher()     // Cipher over a setUserAuthenticationRequired(true) key
    val prompt = BiometricPrompt(
        activity,
        ContextCompat.getMainExecutor(activity),
        object : BiometricPrompt.AuthenticationCallback() {
            override fun onAuthenticationSucceeded(
                result: BiometricPrompt.AuthenticationResult
            ) {
                val crypto = result.cryptoObject ?: return
                decryptWith(crypto.cipher)   // key released only after real success
            }

            override fun onAuthenticationError(code: Int, errString: CharSequence) {
                fallbackToPassword()
            }
        }
    )
    prompt.authenticate(promptInfo, BiometricPrompt.CryptoObject(cipher))
}

// Client: collect the token bound to a server-supplied nonce.
suspend fun fetchIntegrityToken(nonce: String): String =
    integrityManager.requestIntegrityToken(
        IntegrityTokenRequest.builder().setNonce(nonce).build()
    )

// Server, NOT in the app:
fun verifyVerdict(token: String, expectedNonce: String): Verdict {
    val jws = verifyGoogleSignature(token)          // Google keys or Play Console API
    check(jws.requestDetails.nonce == expectedNonce)
    check(System.currentTimeMillis() < jws.expiryTimestamp)
    return Verdict(
        appIntegrity = jws.appIntegrity.appRecognitionVerdict,
        deviceIntegrity = jws.deviceIntegrity.deviceRecognitionVerdict,
        licensing = jws.accountDetails.appLicensingVerdict,
    )
}

fun rootRisk(): Int {
    var score = 0
    if (System.getProperty("ro.build.tags")?.contains("test-keys") == true) score += 2
    if (File("/system/app/Superuser.apk").exists()) score += 1
    if (File("/system/xbin/su").exists() || File("/system/bin/su").exists()) score += 2
    return score
}

